public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    List<Integer> inputNumbers = new ArrayList<>();

    while (sc.hasNextInt()) {
        int capture = sc.nextInt();
        inputNumbers.add(capture);

        if (capture == 0) {
            break;
        }
    }

    for (int i = inputNumbers.size() - 2; i >= 0; i--) { // Start from size - 2 to exclude the zero
        System.out.println(inputNumbers.get(i));
    }
}
